// Feeds RSS/Atom lidos pelo nó "RSS". O Hacker News vem do nó "HN: Algolia".
// weight: prioridade na seleção (3 = alta). max: máximo de itens desta fonte por episódio.
// Fora da lista: Google DeepMind (o feed vem em gzip sem cabeçalho e o nó RSS não lê),
// Anthropic e LangChain (sem feed RSS público).
const sources = [
  { source: 'Simon Willison', url: 'https://simonwillison.net/atom/everything/', weight: 3, max: 2 },
  { source: 'Hugging Face blog', url: 'https://huggingface.co/blog/feed.xml', weight: 3, max: 2 },
  { source: 'OpenAI', url: 'https://openai.com/news/rss.xml', weight: 3, max: 2 },
  { source: 'Google AI blog', url: 'https://blog.google/technology/ai/rss/', weight: 2, max: 1 },
  { source: 'Google for Developers blog', url: 'https://developers.googleblog.com/feeds/posts/default', weight: 2, max: 1 },
  { source: 'GitHub blog', url: 'https://github.blog/ai-and-ml/feed/', weight: 2, max: 1 },
  { source: 'Ollama blog', url: 'https://ollama.com/blog/rss.xml', weight: 2, max: 1 },
  { source: 'Latent Space', url: 'https://www.latent.space/feed', weight: 2, max: 1 },
  { source: 'Interconnects', url: 'https://www.interconnects.ai/feed', weight: 2, max: 1 },
  { source: 'Sebastian Raschka', url: 'https://magazine.sebastianraschka.com/feed', weight: 2, max: 1 },
  { source: 'r/LocalLLaMA', url: 'https://www.reddit.com/r/LocalLLaMA/top/.rss?t=day', weight: 1, max: 2 },
];
return sources.map(s => ({ json: s }));

// Junta RSS + Hacker News, filtra a janela de 24h, limpa, deduplica e escolhe os melhores itens.
const cfg = $('Config').first().json;
const sources = $('Fontes').all().map(i => i.json);
const now = Date.now();
const since = now - cfg.windowHours * 3600e3;

// Fase 3: trocar pela lista de URLs já cobertas, lida do state.json.
const coveredUrls = [];

const HN_KEYWORDS = /\b(AI|LLMs?|GPT[\w.-]*|ChatGPT|Claude|Gemini|Gemma|OpenAI|Anthropic|DeepMind|Mistral|Llama|llama\.cpp|Qwen[\w.-]*|DeepSeek[\w.-]*|agents?|agentic|RAG|MCP|inference|transformers?|embeddings?|fine-?tun\w*|vLLM|Ollama|Copilot|prompts?|tokenizers?|diffusion|distill\w*|Mamba|neural|machine learning|ML|Hugging ?Face|evals?|benchmarks?)\b/i;

const decode = s => s
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#0?39;|&apos;|&#x27;/g, "'").replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n));
const clean = s => decode(String(s || '').replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
const cut = (s, n) => (s.length > n ? s.slice(0, n).replace(/\s+\S*$/, '') + '...' : s);
const normUrl = u => {
  try {
    const x = new URL(u);
    x.hash = '';
    for (const k of [...x.searchParams.keys()]) if (/^(utm_|ref$|source$)/i.test(k)) x.searchParams.delete(k);
    return (x.hostname.replace(/^www\./, '') + x.pathname.replace(/\/+$/, '') + x.search).toLowerCase();
  } catch (e) {
    return String(u || '').toLowerCase();
  }
};
const normTitle = t => clean(t).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const domain = u => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch (e) { return ''; } };

const stats = {};
const failed = [];
const candidates = [];

// RSS: cada item aponta para a fonte de origem pelo pairedItem.
for (const it of $input.all()) {
  const pi = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const src = sources[pi && typeof pi.item === 'number' ? pi.item : -1];
  if (!src) continue;
  const st = (stats[src.source] = stats[src.source] || { fetched: 0, recent: 0 });
  if (it.json.error) {
    failed.push(`${src.source}: ${String(it.json.error.message || it.json.error).slice(0, 150)}`);
    continue;
  }
  if (!it.json.title || !it.json.link) continue;
  st.fetched++;
  const t = Date.parse(it.json.isoDate || it.json.pubDate || '');
  if (!t || t < since || t > now + 3600e3) continue;
  st.recent++;
  candidates.push({
    source: src.source,
    weight: src.weight,
    max: src.max,
    title: clean(it.json.title),
    url: it.json.link,
    published: new Date(t).toISOString(),
    summary: cut(clean(it.json.contentSnippet || it.json.content || it.json.summary)
      .replace(/submitted by \/u\/\S+|\[(link|comments)\]/gi, '').replace(/\s+/g, ' ').trim(), cfg.summaryChars),
  });
}

// Hacker News (Algolia): só histórias com palavras-chave de AI no título.
const hn = $('HN: Algolia').first().json;
if (hn.error) failed.push(`Hacker News: ${String(hn.error.message || hn.error).slice(0, 150)}`);
const hits = Array.isArray(hn.hits) ? hn.hits : [];
stats['Hacker News'] = { fetched: hits.length, recent: 0 };
for (const h of hits) {
  if (!HN_KEYWORDS.test(h.title || '')) continue;
  const t = (h.created_at_i || 0) * 1000;
  if (t < since) continue;
  stats['Hacker News'].recent++;
  const discussion = `https://news.ycombinator.com/item?id=${h.objectID}`;
  candidates.push({
    source: 'Hacker News',
    weight: h.points >= 300 ? 3 : h.points >= 100 ? 2 : 1,
    max: 4,
    title: clean(h.title),
    url: h.url || discussion,
    discussion,
    published: new Date(t).toISOString(),
    summary: '',
    hnPoints: h.points,
    hnComments: h.num_comments || 0,
  });
}

// Seleção: maior peso primeiro, depois mais pontos no HN, depois mais recente.
candidates.sort((a, b) => b.weight - a.weight || (b.hnPoints || 0) - (a.hnPoints || 0) || b.published.localeCompare(a.published));
const covered = new Set(coveredUrls.map(normUrl));
const byUrl = new Map();
const byTitle = new Map();
const perSource = {};
const picked = [];
for (const c of candidates) {
  const nu = normUrl(c.url);
  const nt = normTitle(c.title);
  if (covered.has(nu)) continue;
  const dup = byUrl.get(nu) || (nt && byTitle.get(nt));
  if (dup) {
    // Mesma notícia em duas fontes: enriquece o item já escolhido.
    if (!dup.summary && c.summary) dup.summary = c.summary;
    if (c.hnPoints && !dup.hnPoints) Object.assign(dup, { hnPoints: c.hnPoints, hnComments: c.hnComments, discussion: c.discussion });
    if (c.source !== dup.source && !(dup.alsoOn || []).includes(c.source)) dup.alsoOn = [...(dup.alsoOn || []), c.source];
    continue;
  }
  if (picked.length >= cfg.maxItems || (perSource[c.source] || 0) >= c.max) continue;
  perSource[c.source] = (perSource[c.source] || 0) + 1;
  picked.push(c);
  byUrl.set(nu, c);
  if (nt) byTitle.set(nt, c);
}

const items = picked.map((c, i) => ({
  id: i + 1,
  source: c.source,
  ...(c.alsoOn ? { alsoOn: c.alsoOn } : {}),
  title: c.title,
  url: c.url,
  domain: domain(c.url),
  published: c.published,
  summary: c.summary,
  ...(c.hnPoints ? { hnPoints: c.hnPoints, hnComments: c.hnComments, discussion: c.discussion } : {}),
}));

const date = new Intl.DateTimeFormat('en-CA', { timeZone: cfg.timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(now));
return [{
  json: {
    date,
    mode: items.length >= cfg.minItems ? 'news' : 'slow',
    items,
    candidates: candidates.length,
    stats,
    failed,
  },
}];

// Os prompts moram no repositório (pasta prompts/ da branch main) e são baixados a cada execução.
const base = $('Config').first().json.promptsBaseUrl.replace(/\/+$/, '');
const files = ['hosts.md', 'system-news.md', 'system-slow-day.md', 'show.json', 'topics.json'];
return files.map(name => ({ json: { name, url: `${base}/${name}?t=${Date.now()}` } }));

// Escolhe o modo (notícias ou dia parado), monta intro/outro fixos e a requisição do roteiro.
const cfg = $('Config').first().json;
const news = $('Trata notícias').first().json;
const names = $('Arquivos de prompt').all().map(i => i.json.name);

const files = {};
$input.all().forEach((it, idx) => {
  const pi = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const name = names[pi && typeof pi.item === 'number' ? pi.item : idx];
  if (typeof it.json.data !== 'string' || !it.json.data.trim()) throw new Error(`Prompt vazio ou não baixado: ${name}`);
  files[name] = it.json.data;
});
for (const n of names) if (!files[n]) throw new Error(`Prompt não baixado: ${n}`);
const show = JSON.parse(files['show.json']);
const topics = JSON.parse(files['topics.json']);

const mode = news.mode;
const dateSpoken = new Intl.DateTimeFormat('en-US', { timeZone: cfg.timezone, weekday: 'long', month: 'long', day: 'numeric' }).format(new Date());

// Dia parado: tema escolhido pelo número do dia, então nenhum tema se repete em menos de topics.length dias.
let topic = null;
if (mode === 'slow') {
  const [y, m, d] = news.date.split('-').map(Number);
  topic = topics[Math.floor(Date.UTC(y, m - 1, d) / 86400e3) % topics.length];
}

const fill = s => s.replace('{DATE}', dateSpoken).replace('{TOPIC}', topic ? topic.title : '');
const toLines = arr => arr.map(([speaker, text]) => ({ speaker, text: fill(text) }));
const intro = toLines(show[mode === 'news' ? 'intro_news' : 'intro_slow']);
const outro = toLines(show[mode === 'news' ? 'outro_news' : 'outro_slow']);

// Faixa de palavras pedida ao modelo: o total do episódio menos intro/outro, com folga de 20% de cada lado.
const words = s => s.split(/\s+/).filter(Boolean).length;
const fixedWords = [...intro, ...outro].reduce((n, l) => n + words(l.text), 0);
const bodyMin = cfg.minWords - fixedWords;
const bodyMax = cfg.maxWords - fixedWords;
const margin = Math.round((bodyMax - bodyMin) * 0.2);
const vars = {
  BODY_MIN_WORDS: bodyMin + margin,
  BODY_MAX_WORDS: bodyMax - margin,
  BODY_TARGET_WORDS: Math.round((bodyMin + bodyMax) / 2),
};
const system = (files['hosts.md'] + '\n\n' + files[mode === 'news' ? 'system-news.md' : 'system-slow-day.md'])
  .replace(/\{\{(\w+)\}\}/g, (m, k) => (k in vars ? String(vars[k]) : m));

let user;
if (mode === 'news') {
  user = `Today is ${dateSpoken}. Candidate items from the last 24 hours:\n\n` + news.items.map(it => [
    `[${it.id}] ${it.source}${it.alsoOn ? ` (also on ${it.alsoOn.join(', ')})` : ''}`,
    `Title: ${it.title}`,
    it.domain ? `Link domain: ${it.domain}` : null,
    it.hnPoints ? `Hacker News: ${it.hnPoints} points, ${it.hnComments} comments` : null,
    `Summary: ${it.summary || '(title only)'}`,
  ].filter(Boolean).join('\n')).join('\n\n');
} else {
  user = `Today is ${dateSpoken}.\nTopic: ${topic.title}\nSuggested angle: ${topic.angle}`;
}

const request = {
  systemInstruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: user }] }],
  generationConfig: {
    temperature: 0.9,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        title: { type: 'STRING' },
        summary: { type: 'STRING' },
        covered: { type: 'ARRAY', items: { type: 'INTEGER' } },
        lines: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              speaker: { type: 'STRING', enum: ['Lucas', 'Sarah'] },
              text: { type: 'STRING' },
            },
            required: ['speaker', 'text'],
          },
        },
      },
      required: ['title', 'summary', 'covered', 'lines'],
      propertyOrdering: ['title', 'summary', 'covered', 'lines'],
    },
  },
};

return [{ json: { mode, date: news.date, dateSpoken, topic, intro, outro, bodyWords: vars, request } }];

// Monta o corpo da chamada do roteiro. Numa nova tentativa, devolve ao modelo o motivo da reprovação.
const base = $('Monta prompt').first().json.request;
const prev = $input.first().json;
const body = JSON.parse(JSON.stringify(base));
if (Array.isArray(prev.errors) && prev.errors.length) {
  if (prev.rawText) body.contents.push({ role: 'model', parts: [{ text: prev.rawText }] });
  body.contents.push({
    role: 'user',
    parts: [{ text: `Your previous script was rejected: ${prev.errors.join(' ')} Write a new script that fixes this and follows every rule.` }],
  });
}
return [{ json: { body, attempt: $runIndex + 1 } }];

// Guardrails do roteiro: JSON válido, falantes certos, número de falas e de palavras.
const cfg = $('Config').first().json;
const mp = $('Monta prompt').first().json;
const news = $('Trata notícias').first().json;
const res = $input.first().json;

const words = s => s.split(/\s+/).filter(Boolean).length;
const cleanText = s => String(s || '')
  .replace(/https?:\/\/\S+/g, '')
  .replace(/\((?:laugh|chuckl|sigh|paus|smil|giggl)[^)]*\)|\[[^\]]*\]/gi, '')
  .replace(/[*_#`~]/g, '')
  .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, '')
  .replace(/\s+/g, ' ')
  .trim();

const errors = [];
let rawText = '';
let parsed = null;
const cand = res.candidates && res.candidates[0];
if (res.error) {
  errors.push(`API error: ${JSON.stringify(res.error).slice(0, 300)}`);
} else if (!cand) {
  errors.push(`No candidate in the response: ${JSON.stringify(res.promptFeedback || res).slice(0, 300)}`);
} else {
  if (cand.finishReason && cand.finishReason !== 'STOP') errors.push(`The answer stopped early (${cand.finishReason}).`);
  rawText = ((cand.content && cand.content.parts) || []).filter(p => !p.thought && typeof p.text === 'string').map(p => p.text).join('');
  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    errors.push('The output was not valid JSON.');
  }
}

let lines = [];
let wordCount = 0;
let covered = [];
if (parsed) {
  const body = [];
  for (const l of Array.isArray(parsed.lines) ? parsed.lines : []) {
    const speaker = String((l && l.speaker) || '').trim();
    if (speaker !== 'Lucas' && speaker !== 'Sarah') {
      errors.push(`Invalid speaker "${speaker}"; use only "Lucas" and "Sarah".`);
      continue;
    }
    const text = cleanText(l.text);
    if (text) body.push({ speaker, text });
  }
  if (body.length < cfg.minTurns) errors.push(`The script has only ${body.length} turns; write at least ${cfg.minTurns}.`);

  // Junta falas seguidas do mesmo host (inclusive na emenda com a intro e a outro).
  for (const l of [...mp.intro, ...body, ...mp.outro]) {
    const last = lines[lines.length - 1];
    if (last && last.speaker === l.speaker) last.text += ' ' + l.text;
    else lines.push({ speaker: l.speaker, text: l.text });
  }
  const bodyWords = body.reduce((n, l) => n + words(l.text), 0);
  wordCount = lines.reduce((n, l) => n + words(l.text), 0);
  if (wordCount < cfg.minWords || wordCount > cfg.maxWords) {
    const fixed = wordCount - bodyWords;
    errors.push(`Your lines have ${bodyWords} words; they must have between ${cfg.minWords - fixed} and ${cfg.maxWords - fixed}. ${wordCount < cfg.minWords ? 'Write more.' : 'Write less.'}`);
  }
  if (typeof parsed.title !== 'string' || !parsed.title.trim()) errors.push('"title" is missing.');

  const ids = new Set(news.items.map(i => i.id));
  covered = [...new Set((Array.isArray(parsed.covered) ? parsed.covered : []).map(Number))].filter(n => ids.has(n));
  if (mp.mode === 'news' && !covered.length) errors.push('"covered" must list the ids of the items you talked about.');
}

return [{
  json: {
    ok: errors.length === 0,
    attempt: $runIndex + 1,
    errors,
    rawText,
    script: {
      title: parsed && typeof parsed.title === 'string' ? cleanText(parsed.title) : '',
      summary: parsed && typeof parsed.summary === 'string' ? cleanText(parsed.summary) : '',
      covered,
      wordCount,
      lines,
    },
  },
}];

// Monta a chamada de TTS multi-speaker e o nome dos arquivos do episódio.
const cfg = $('Config').first().json;
const mp = $('Monta prompt').first().json;
const { script, attempt } = $input.first().json;

const text = [cfg.ttsStyle, '', ...script.lines.map(l => `${l.speaker}: ${l.text}`)].join('\n');
const hhmm = new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
  .format(new Date()).replace(':', '');
const fileBase = `${cfg.outDir.replace(/\/+$/, '')}/${mp.date}-${hhmm}`;

const body = {
  contents: [{ parts: [{ text }] }],
  generationConfig: {
    responseModalities: ['AUDIO'],
    speechConfig: {
      multiSpeakerVoiceConfig: {
        speakerVoiceConfigs: [
          { speaker: 'Lucas', voiceConfig: { prebuiltVoiceConfig: { voiceName: cfg.voiceLucas } } },
          { speaker: 'Sarah', voiceConfig: { prebuiltVoiceConfig: { voiceName: cfg.voiceSarah } } },
        ],
      },
    },
  },
};
return [{ json: { body, fileBase, script, attempt } }];

const res = $input.first().json;
const parts = (res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || [];
const part = parts.find(p => p.inlineData);
if (!part) throw new Error('TTS sem áudio: ' + JSON.stringify(res).slice(0, 500));
const m = /rate=(\d+)/.exec(part.inlineData.mimeType || '');
return [{ json: { audio: part.inlineData.data, mimeType: part.inlineData.mimeType, sampleRate: m ? Number(m[1]) : 24000 } }];

// Relatório do episódio, gravado ao lado do MP3 para revisão (e base das show notes na Fase 3).
const cfg = $('Config').first().json;
const news = $('Trata notícias').first().json;
const mp = $('Monta prompt').first().json;
const v = $('Monta TTS').first().json;
const fileBase = v.fileBase;
const duration = Number(String($input.first().json.stdout || '').trim());

const warnings = [];
if (!(duration >= 90 && duration <= 240)) warnings.push(`Duração fora de 1,5–4 min: ${duration}s`);
if (news.failed.length) warnings.push(`Fontes com erro: ${news.failed.length}`);

const covered = new Set(v.script.covered);
return [{
  json: {
    generatedAt: new Date().toISOString(),
    date: mp.date,
    mode: mp.mode,
    topic: mp.topic,
    title: v.script.title,
    summary: v.script.summary,
    mp3: `${fileBase}.mp3`,
    durationSeconds: duration,
    wordCount: v.script.wordCount,
    scriptAttempts: v.attempt,
    models: { text: cfg.textModel, tts: cfg.ttsModel, voices: { Lucas: cfg.voiceLucas, Sarah: cfg.voiceSarah } },
    warnings,
    sources: news.items.filter(i => covered.has(i.id)).map(i => ({ id: i.id, source: i.source, title: i.title, url: i.url, discussion: i.discussion })),
    notCovered: news.items.filter(i => !covered.has(i.id)).map(i => ({ id: i.id, source: i.source, title: i.title })),
    collection: { candidates: news.candidates, stats: news.stats, failed: news.failed },
    lines: v.script.lines,
  },
}];
